// Variable declarations
int max_attempts = 3;
bool success = false;

// Expression statements
success = try_connect();
max_attempts = max_attempts - 1;

// Function calls
log_event("Connection failed");

// Definition termination (often forgotten)
struct Result {
    int code;
    float time;
} last_result; // <-- Semicolon required here

// Control structures (the structure itself does not terminate)
while (!success) {
    // Statements within the block DO terminate
    wait_time(100);
}
